import { useEffect, useMemo, useRef, useState } from 'react';
import { SearchX } from 'lucide-react';
import './index.css';
import type { QuickFilter, Status, Task, View } from './lib/types';
import { statusLabel } from './lib/types';
import { isOverdue, isThisWeek } from './lib/dates';
import { usePersisted, useTasks } from './lib/store';
import { ME, PEOPLE, PROJECTS } from './data/seed';
import Sidebar from './components/Sidebar';
import ProjectHeader from './components/ProjectHeader';
import Board from './components/Board';
import ListView from './components/ListView';
import Overview from './components/Overview';
import TaskDetail from './components/TaskDetail';
import TaskForm from './components/TaskForm';
import { Toast } from './components/ui';

type ToastState = { message: string; action?: { label: string; run: () => void } } | null;

export default function App() {
  const { tasks, update, move, create, remove, restore, reset } = useTasks();
  const [projectId, setProjectId] = usePersisted('ritmo:proyecto', PROJECTS[0].id);
  const [view, setView] = usePersisted<View>('ritmo:vista', 'tablero');
  const [filter, setFilter] = useState<QuickFilter>('todas');
  const [query, setQuery] = useState('');
  const [assignee, setAssignee] = useState<string | null>(null);
  const [openId, setOpenId] = useState<string | null>(null);
  const [creating, setCreating] = useState<Status | null>(null);
  const [drawer, setDrawer] = useState(false);
  const [toast, setToast] = useState<ToastState>(null);
  const toastTimer = useRef<number>();

  const project = PROJECTS.find(p => p.id === projectId) ?? PROJECTS[0];
  const me = PEOPLE.find(p => p.id === ME)!;
  const projectTasks = useMemo(() => tasks.filter(t => t.projectId === project.id), [tasks, project.id]);

  const visible = useMemo(() => {
    const q = query.trim().toLowerCase();
    return projectTasks.filter(t => {
      if (filter === 'mias' && t.assigneeId !== ME) return false;
      if (filter === 'semana' && !isThisWeek(t)) return false;
      if (filter === 'atrasadas' && !isOverdue(t)) return false;
      if (assignee && t.assigneeId !== assignee) return false;
      if (q && !`${project.key}-${t.number} ${t.title} ${t.tags.join(' ')}`.toLowerCase().includes(q)) return false;
      return true;
    });
  }, [projectTasks, filter, assignee, query, project.key]);

  const notify = (t: ToastState) => {
    setToast(t);
    window.clearTimeout(toastTimer.current);
    toastTimer.current = window.setTimeout(() => setToast(null), 4500);
  };
  useEffect(() => () => window.clearTimeout(toastTimer.current), []);

  const code = (t: Task) => `${project.key}-${t.number}`;

  const handleMove = (id: string, status: Status, beforeId: string | null = null) => {
    const t = tasks.find(x => x.id === id);
    if (!t) return;
    move(id, status, beforeId);
    if (t.status !== status) notify({ message: `${code(t)} movida a ${statusLabel(status)}` });
  };
  const handleDelete = (id: string) => {
    const t = tasks.find(x => x.id === id);
    if (!t) return;
    remove(id);
    setOpenId(null);
    notify({ message: `${code(t)} eliminada`, action: { label: 'Deshacer', run: () => { restore(t); setToast(null); } } });
  };
  const selectProject = (id: string) => {
    setProjectId(id);
    setFilter('todas');
    setAssignee(null);
    setQuery('');
    setDrawer(false);
  };

  const actions = { onOpen: setOpenId, onMove: handleMove, onDelete: handleDelete };
  const openTask = tasks.find(t => t.id === openId);
  const filtering = filter !== 'todas' || !!assignee || !!query.trim();

  const sidebar = (
    <Sidebar projects={PROJECTS} tasks={tasks} people={PEOPLE} me={me} currentId={project.id} onSelect={selectProject}
      onReset={() => { reset(); setOpenId(null); notify({ message: 'Datos de ejemplo restablecidos' }); }} />
  );

  return (
    <div className="rt-app flex h-screen min-h-[560px] overflow-hidden bg-[#F5F6FA] text-[#14162B]">
      <aside className="hidden w-[244px] shrink-0 lg:block">{sidebar}</aside>

      {drawer && (
        <div className="fixed inset-0 z-40 lg:hidden" role="dialog" aria-modal="true" aria-label="Menú">
          <div className="rt-fade absolute inset-0 bg-[#14162B]/50" onClick={() => setDrawer(false)} />
          <div className="rt-pop absolute inset-y-0 left-0 w-[280px] max-w-[85vw]">{sidebar}</div>
        </div>
      )}

      <main className="flex min-w-0 flex-1 flex-col">
        <ProjectHeader project={project} tasks={projectTasks} people={PEOPLE} meId={ME} view={view} onView={setView}
          filter={filter} onFilter={setFilter} query={query} onQuery={setQuery} assignee={assignee} onAssignee={setAssignee}
          onNew={() => setCreating('todo')} onMenu={() => setDrawer(true)} />

        <div className="min-h-0 flex-1 pt-4">
          {view !== 'resumen' && filtering && visible.length === 0 ? (
            <div className="mx-4 flex flex-col items-center rounded-2xl border border-dashed border-[#D3D7E3] px-6 py-14 text-center md:mx-6">
              <SearchX size={28} className="text-[#8A90A6]" aria-hidden />
              <p className="rt-display mt-3 text-lg font-semibold">Ninguna tarea coincide</p>
              <p className="mt-1 max-w-sm text-sm text-[#5A6078]">Prueba con otra búsqueda o quita los filtros para ver todo el proyecto.</p>
              <button type="button" onClick={() => { setFilter('todas'); setAssignee(null); setQuery(''); }}
                className="mt-4 rounded-xl bg-[#14162B] px-4 py-2 text-sm font-semibold text-white">Quitar filtros</button>
            </div>
          ) : view === 'tablero' ? (
            <Board tasks={visible} project={project} people={PEOPLE} onAdd={setCreating} {...actions} />
          ) : view === 'lista' ? (
            <ListView tasks={visible} project={project} people={PEOPLE} onAdd={setCreating} {...actions} />
          ) : (
            <Overview tasks={projectTasks} project={project} people={PEOPLE} onOpen={setOpenId} />
          )}
        </div>
      </main>

      {openTask && (
        <TaskDetail key={openTask.id} task={openTask} project={PROJECTS.find(p => p.id === openTask.projectId)!} people={PEOPLE}
          onChange={patch => update(openTask.id, patch)} onMove={s => handleMove(openTask.id, s)}
          onDelete={() => handleDelete(openTask.id)} onClose={() => setOpenId(null)} />
      )}

      {creating && (
        <TaskForm project={project} people={PEOPLE} initialStatus={creating} defaultAssignee={ME} onClose={() => setCreating(null)}
          onCreate={data => {
            const t = create(data);
            setCreating(null);
            notify({ message: `${project.key}-${t.number} creada en ${statusLabel(t.status)}`, action: { label: 'Abrir', run: () => { setOpenId(t.id); setToast(null); } } });
          }} />
      )}

      {toast && <Toast message={toast.message} actionLabel={toast.action?.label} onAction={toast.action?.run} />}
    </div>
  );
}

import { useRef, useState } from 'react';
import { Plus } from 'lucide-react';
import clsx from 'clsx';
import type { Person, Project, Status, Task } from '../lib/types';
import { STATUSES } from '../lib/types';
import TaskCard, { type TaskActions } from './TaskCard';

interface Props extends TaskActions {
  tasks: Task[];
  project: Project;
  people: Person[];
  onAdd: (status: Status) => void;
}

type Over = { status: Status; beforeId: string | null };

export default function Board({ tasks, project, people, onAdd, ...actions }: Props) {
  const [dragId, setDragId] = useState<string | null>(null);
  const [over, setOver] = useState<Over | null>(null);
  const lists = useRef<Partial<Record<Status, HTMLDivElement | null>>>({});

  const byStatus = (s: Status) => tasks.filter(t => t.status === s).sort((a, b) => a.order - b.order);

  const computeOver = (status: Status, y: number): Over => {
    const el = lists.current[status];
    const cards = Array.from(el?.querySelectorAll<HTMLElement>('[data-card]') ?? []).filter(c => c.dataset.card !== dragId);
    const next = cards.find(c => {
      const r = c.getBoundingClientRect();
      return y < r.top + r.height / 2;
    });
    return { status, beforeId: next?.dataset.card ?? null };
  };

  const finish = () => { setDragId(null); setOver(null); };

  return (
    <div className="rt-scroll flex h-full snap-x snap-mandatory scroll-px-4 gap-3 overflow-x-auto px-4 pb-4 md:snap-none md:px-6">
      {STATUSES.map(s => {
        const col = byStatus(s.id);
        const isOver = over?.status === s.id && !!dragId;
        const visible = col.filter(t => t.id !== dragId);
        const placeholder = <div key="ph" className="h-1 rounded-full bg-[#5B47F5]" aria-hidden />;
        return (
          <section
            key={s.id}
            aria-label={`Columna ${s.label}`}
            onDragOver={e => {
              if (!dragId) return;
              e.preventDefault();
              e.dataTransfer.dropEffect = 'move';
              const o = computeOver(s.id, e.clientY);
              if (o.status !== over?.status || o.beforeId !== over?.beforeId) setOver(o);
            }}
            onDragLeave={e => {
              if (!e.currentTarget.contains(e.relatedTarget as Node)) setOver(o => (o?.status === s.id ? null : o));
            }}
            onDrop={e => {
              e.preventDefault();
              const id = dragId || e.dataTransfer.getData('text/plain');
              if (id) {
                const o = computeOver(s.id, e.clientY);
                actions.onMove(id, s.id, o.beforeId);
              }
              finish();
            }}
            className={clsx(
              'flex w-[82vw] shrink-0 snap-start flex-col rounded-2xl border transition-colors sm:w-[290px] lg:w-auto lg:min-w-[220px] lg:flex-1 lg:shrink',
              isOver ? 'border-[#B9B0FB] bg-[#EEECFE]' : 'border-transparent bg-[#ECEEF4]',
            )}
          >
            <header className="flex items-center gap-2 px-3 pb-2 pt-3">
              <span className="h-2.5 w-2.5 rounded-full" style={{ background: s.color }} aria-hidden />
              <h3 className="text-sm font-bold text-[#14162B]">{s.label}</h3>
              <span className="rounded-full bg-white px-2 py-px text-xs font-semibold text-[#5A6078]">{col.length}</span>
              <button
                type="button"
                onClick={() => onAdd(s.id)}
                aria-label={`Añadir tarea en ${s.label}`}
                className="ml-auto grid h-7 w-7 place-items-center rounded-lg text-[#5A6078] hover:bg-white hover:text-[#14162B]"
              >
                <Plus size={16} aria-hidden />
              </button>
            </header>
            <div ref={el => { lists.current[s.id] = el; }} className="rt-scroll flex min-h-[120px] flex-1 flex-col gap-2 overflow-y-auto px-2 pb-2">
              {col.map(t => (
                <div key={t.id} className="flex flex-col gap-2">
                  {isOver && over?.beforeId === t.id && t.id !== dragId && visible.includes(t) && placeholder}
                  <TaskCard
                    task={t}
                    project={project}
                    assignee={people.find(p => p.id === t.assigneeId)}
                    dragging={dragId === t.id}
                    onDragStart={setDragId}
                    onDragEnd={finish}
                    {...actions}
                  />
                </div>
              ))}
              {isOver && over?.beforeId === null && placeholder}
              {col.length === 0 && !isOver && (
                <button
                  type="button"
                  onClick={() => onAdd(s.id)}
                  className="flex flex-1 flex-col items-center justify-center gap-1 rounded-xl border-2 border-dashed border-[#D3D7E3] px-4 py-6 text-center text-sm text-[#6B7189] hover:border-[#B9B0FB] hover:text-[#4433C9]"
                >
                  <span className="font-semibold">Sin tareas aquí</span>
                  <span className="text-xs">Arrastra una tarjeta o pulsa para añadir</span>
                </button>
              )}
            </div>
          </section>
        );
      })}
    </div>
  );
}

import { useState } from 'react';
import { ChevronDown, Plus } from 'lucide-react';
import clsx from 'clsx';
import type { Person, Project, Status, Task } from '../lib/types';
import { STATUSES, priorityRank } from '../lib/types';
import { Avatar, DueChip, PriorityIcon, StatusDot, SubtaskMeter, TagChip } from './ui';
import { MoveMenu, type TaskActions } from './TaskCard';

type Sort = 'manual' | 'fecha' | 'prioridad';

interface Props extends TaskActions {
  tasks: Task[];
  project: Project;
  people: Person[];
  onAdd: (status: Status) => void;
}

export default function ListView({ tasks, project, people, onAdd, onOpen, onMove, onDelete }: Props) {
  const [sort, setSort] = useState<Sort>('manual');
  const [collapsed, setCollapsed] = useState<Partial<Record<Status, boolean>>>({ done: false });

  const sorter = (a: Task, b: Task) => {
    if (sort === 'fecha') return (a.due ?? '9999').localeCompare(b.due ?? '9999');
    if (sort === 'prioridad') return priorityRank(a.priority) - priorityRank(b.priority);
    return a.order - b.order;
  };

  return (
    <div className="rt-scroll h-full overflow-y-auto px-4 pb-10 md:px-6">
      <div className="mb-3 flex items-center justify-end gap-2 text-sm">
        <label htmlFor="rt-sort" className="text-[#5A6078]">Ordenar por</label>
        <select id="rt-sort" value={sort} onChange={e => setSort(e.target.value as Sort)}
          className="rounded-lg border border-[#DADDE8] bg-white px-2.5 py-1.5 font-semibold text-[#14162B]">
          <option value="manual">Orden del tablero</option>
          <option value="fecha">Fecha límite</option>
          <option value="prioridad">Prioridad</option>
        </select>
      </div>

      <div className="overflow-hidden rounded-2xl border border-[#E4E7F0] bg-white">
        {STATUSES.map(s => {
          const rows = tasks.filter(t => t.status === s.id).sort(sorter);
          const isCollapsed = !!collapsed[s.id];
          return (
            <section key={s.id} className="border-b border-[#EDEFF5] last:border-b-0">
              <div className="flex items-center gap-2 bg-[#F7F8FB] px-3 py-2 md:px-4">
                <button type="button" aria-expanded={!isCollapsed}
                  onClick={() => setCollapsed(c => ({ ...c, [s.id]: !isCollapsed }))}
                  className="flex items-center gap-2 rounded-md py-0.5 pr-2 text-sm font-bold text-[#14162B]">
                  <ChevronDown size={16} className={clsx('text-[#6B7189] transition-transform', isCollapsed && '-rotate-90')} aria-hidden />
                  <StatusDot status={s.id} />
                  {s.label}
                  <span className="font-semibold text-[#8A90A6]">{rows.length}</span>
                </button>
                <button type="button" onClick={() => onAdd(s.id)} aria-label={`Añadir tarea en ${s.label}`}
                  className="ml-auto grid h-7 w-7 place-items-center rounded-md text-[#5A6078] hover:bg-white">
                  <Plus size={15} aria-hidden />
                </button>
              </div>
              {!isCollapsed && rows.length === 0 && (
                <p className="px-4 py-3 pl-11 text-sm text-[#8A90A6]">Ninguna tarea en este estado con los filtros actuales.</p>
              )}
              {!isCollapsed && rows.map(t => {
                const person = people.find(p => p.id === t.assigneeId);
                const done = t.status === 'done';
                return (
                  <div key={t.id} role="button" tabIndex={0} onClick={() => onOpen(t.id)}
                    onKeyDown={e => { if (e.key === 'Enter') onOpen(t.id); }}
                    className="group flex cursor-pointer items-center gap-3 border-t border-[#F0F1F6] px-3 py-2.5 hover:bg-[#FAFAFE] md:px-4">
                    <button type="button" aria-label={done ? 'Marcar como pendiente' : 'Marcar como hecha'}
                      onClick={e => { e.stopPropagation(); onMove(t.id, done ? 'todo' : 'done'); }}
                      className={clsx('grid h-5 w-5 shrink-0 place-items-center rounded-full border-2 transition-colors',
                        done ? 'border-[#12A57A] bg-[#12A57A] text-white' : 'border-[#C3C7D6] hover:border-[#12A57A]')}>
                      {done && <svg width="10" height="10" viewBox="0 0 10 10" aria-hidden><path d="M2 5.2l2 2 4-4.4" stroke="currentColor" strokeWidth="1.8" fill="none" strokeLinecap="round" /></svg>}
                    </button>
                    <PriorityIcon p={t.priority} />
                    <span className="rt-mono hidden w-14 shrink-0 text-[#8A90A6] sm:block">{project.key}-{t.number}</span>
                    <span className={clsx('line-clamp-2 min-w-0 flex-1 text-sm font-semibold', done ? 'text-[#8A90A6] line-through' : 'text-[#14162B]')}>
                      {t.title}
                    </span>
                    <span className="hidden gap-1 lg:flex">{t.tags.map(g => <TagChip key={g} name={g} small />)}</span>
                    <span className="hidden w-12 sm:block"><SubtaskMeter task={t} /></span>
                    <span className="shrink-0 text-right sm:w-[92px]"><DueChip task={t} compact /></span>
                    <Avatar person={person} size={24} />
                    <span className="-mr-1" onClick={e => e.stopPropagation()}>
                      <MoveMenu task={t} onMove={st => onMove(t.id, st)} onOpen={() => onOpen(t.id)} onDelete={() => onDelete(t.id)} />
                    </span>
                  </div>
                );
              })}
            </section>
          );
        })}
      </div>
    </div>
  );
}

import { useEffect, useState } from 'react';
import { AlarmClock, CheckCircle2, CircleDot, Flame } from 'lucide-react';
import type { Person, Project, Task } from '../lib/types';
import { STATUSES } from '../lib/types';
import { dueLabel, isOverdue, isThisWeek } from '../lib/dates';
import { Avatar, PriorityIcon, StatusDot } from './ui';

interface Props {
  tasks: Task[];
  project: Project;
  people: Person[];
  onOpen: (id: string) => void;
}

function useMounted() {
  const [m, setM] = useState(false);
  useEffect(() => { const id = requestAnimationFrame(() => setM(true)); return () => cancelAnimationFrame(id); }, []);
  return m;
}

export default function Overview({ tasks, project, people, onOpen }: Props) {
  const mounted = useMounted();
  const [hover, setHover] = useState<string | null>(null);
  const total = tasks.length;
  const done = tasks.filter(t => t.status === 'done').length;
  const overdue = tasks.filter(isOverdue).length;
  const week = tasks.filter(isThisWeek).length;
  const pct = total ? Math.round((done / total) * 100) : 0;

  const tiles = [
    { label: 'Abiertas', value: total - done, icon: CircleDot, color: '#5B47F5' },
    { label: 'Completadas', value: done, icon: CheckCircle2, color: '#12A57A' },
    { label: 'Vencen esta semana', value: week, icon: AlarmClock, color: '#B87700' },
    { label: 'Atrasadas', value: overdue, icon: Flame, color: '#DC3D4B' },
  ];

  // Dona por estado
  const R = 58;
  const C = 2 * Math.PI * R;
  let acc = 0;
  const arcs = STATUSES.map(s => {
    const n = tasks.filter(t => t.status === s.id).length;
    const len = total ? (n / total) * C : 0;
    const arc = { ...s, n, len, offset: acc };
    acc += len;
    return arc;
  });
  const hovered = arcs.find(a => a.id === hover);

  // Carga por persona (tareas abiertas por estado)
  const members = people.filter(p => project.memberIds.includes(p.id));
  const load = members.map(p => {
    const mine = tasks.filter(t => t.assigneeId === p.id && t.status !== 'done');
    return { p, todo: mine.filter(t => t.status === 'todo').length, doing: mine.filter(t => t.status === 'doing').length, review: mine.filter(t => t.status === 'review').length, total: mine.length };
  });
  const maxLoad = Math.max(4, ...load.map(l => l.total));

  const upcoming = tasks.filter(t => t.due && t.status !== 'done').sort((a, b) => a.due!.localeCompare(b.due!)).slice(0, 6);

  return (
    <div className="rt-scroll h-full overflow-y-auto px-4 pb-10 md:px-6">
      <div className="grid grid-cols-2 gap-3 lg:grid-cols-4">
        {tiles.map(t => (
          <div key={t.label} className="rounded-2xl border border-[#E4E7F0] bg-white p-4">
            <div className="flex items-center gap-2 text-sm font-semibold text-[#5A6078]">
              <t.icon size={16} style={{ color: t.color }} aria-hidden /> {t.label}
            </div>
            <p className="rt-display mt-2 text-3xl font-bold text-[#14162B]">{t.value}</p>
          </div>
        ))}
      </div>

      <div className="mt-4 grid gap-4 lg:grid-cols-[1fr_1.4fr]">
        <section className="rounded-2xl border border-[#E4E7F0] bg-white p-5">
          <h3 className="rt-display text-lg font-semibold text-[#14162B]">Estado del proyecto</h3>
          <p className="text-sm text-[#5A6078]">{done} de {total} tareas terminadas</p>
          <div className="mt-4 flex flex-wrap items-center gap-6">
            <div className="relative">
              <svg width="160" height="160" viewBox="0 0 160 160" role="img" aria-label={`Progreso ${pct}%`}>
                <circle cx="80" cy="80" r={R} fill="none" stroke="#EEF0F5" strokeWidth="18" />
                {arcs.map(a => a.len > 0 && (
                  <circle key={a.id} className="rt-arc cursor-pointer" cx="80" cy="80" r={R} fill="none" stroke={a.color}
                    strokeWidth={hover === a.id ? 22 : 18}
                    strokeDasharray={`${mounted ? Math.max(0, a.len - 2) : 0} ${C}`}
                    strokeDashoffset={-a.offset} transform="rotate(-90 80 80)"
                    onMouseEnter={() => setHover(a.id)} onMouseLeave={() => setHover(null)} />
                ))}
              </svg>
              <div className="pointer-events-none absolute inset-0 flex flex-col items-center justify-center text-center">
                <span className="rt-display text-3xl font-bold text-[#14162B]">{hovered ? hovered.n : `${pct}%`}</span>
                <span className="text-xs font-semibold text-[#5A6078]">{hovered ? hovered.label : 'completado'}</span>
              </div>
            </div>
            <ul className="flex-1 space-y-2 text-sm">
              {arcs.map(a => (
                <li key={a.id} onMouseEnter={() => setHover(a.id)} onMouseLeave={() => setHover(null)}
                  className="flex items-center gap-2 rounded-lg px-2 py-1 hover:bg-[#F5F6FA]">
                  <StatusDot status={a.id} />
                  <span className="flex-1 text-[#2A2D45]">{a.label}</span>
                  <span className="font-bold text-[#14162B]">{a.n}</span>
                </li>
              ))}
            </ul>
          </div>
        </section>

        <section className="rounded-2xl border border-[#E4E7F0] bg-white p-5">
          <h3 className="rt-display text-lg font-semibold text-[#14162B]">Carga del equipo</h3>
          <p className="text-sm text-[#5A6078]">Tareas abiertas por persona</p>
          <div className="mt-4 space-y-3">
            {load.map(({ p, todo, doing, review, total: n }) => (
              <div key={p.id} className="group flex items-center gap-3">
                <Avatar person={p} size={30} />
                <div className="w-28 shrink-0 sm:w-36">
                  <p className="truncate text-sm font-semibold text-[#14162B]">{p.name}</p>
                  <p className="truncate text-xs text-[#6B7189]">{p.role}</p>
                </div>
                <div className="relative flex h-3 flex-1 overflow-hidden rounded-full bg-[#EEF0F5]">
                  {([['todo', todo], ['doing', doing], ['review', review]] as const).map(([k, v]) => (
                    <div key={k} className="rt-bar h-full" title={`${STATUSES.find(s => s.id === k)!.label}: ${v}`}
                      style={{ width: mounted ? `${(v / maxLoad) * 100}%` : 0, background: STATUSES.find(s => s.id === k)!.color }} />
                  ))}
                </div>
