import { useEffect, useRef, useState } from 'react';
import clsx from 'clsx';
import { AlignLeft, Check, MoreHorizontal, PanelRightOpen, Trash2 } from 'lucide-react';
import type { Person, Project, Status, Task } from '../lib/types';
import { STATUSES } from '../lib/types';
import { Avatar, DueChip, PriorityIcon, StatusDot, SubtaskMeter, TagChip } from './ui';

export interface TaskActions {
  onOpen: (id: string) => void;
  onMove: (id: string, status: Status, beforeId?: string | null) => void;
  onDelete: (id: string) => void;
}

interface Props extends TaskActions {
