  project: Project;
  assignee?: Person;
  dragging: boolean;
  onDragStart: (id: string) => void;
  onDragEnd: () => void;
}

export default function TaskCard({ task, project, assignee, dragging, onDragStart, onDragEnd, onOpen, onMove, onDelete }: Props) {
