interface MenuProps {
  task: Task;
  onMove: (status: Status) => void;
  onOpen: () => void;
  onDelete: () => void;
}

/** Menú de acciones de una tarea: alternativa táctil y de teclado al arrastrar. */
export function MoveMenu({ task, onMove, onOpen, onDelete }: MenuProps) {
  const [pos, setPos] = useState<{ top: number; left: number } | null>(null);
  const btn = useRef<HTMLButtonElement>(null);
  const menu = useRef<HTMLDivElement>(null);

  const open = () => {
    const r = btn.current!.getBoundingClientRect();
    const w = 224;
    const h = 260;
    const left = Math.min(Math.max(8, r.right - w), window.innerWidth - w - 8);
    const top = r.bottom + h > window.innerHeight - 8 ? Math.max(8, r.top - h - 4) : r.bottom + 4;
    setPos({ top, left });
  };
  const close = (focusBack = true) => {
    setPos(null);
    if (focusBack) btn.current?.focus();
  };

  useEffect(() => {
    if (!pos) return;
    menu.current?.querySelector<HTMLButtonElement>('button:not(:disabled)')?.focus({ preventScroll: true });
    const onDown = (e: MouseEvent) => {
      if (!menu.current?.contains(e.target as Node) && !btn.current?.contains(e.target as Node)) close(false);
    };
    const onKey = (e: KeyboardEvent) => {
      if (e.key === 'Escape') { e.stopPropagation(); close(); }
      if (e.key === 'ArrowDown' || e.key === 'ArrowUp') {
        e.preventDefault();
        const items = Array.from(menu.current?.querySelectorAll<HTMLButtonElement>('button:not(:disabled)') ?? []);
        const i = items.indexOf(document.activeElement as HTMLButtonElement);
        items[(i + (e.key === 'ArrowDown' ? 1 : -1) + items.length) % items.length]?.focus({ preventScroll: true });
      }
    };
    const onScroll = () => close(false);
    document.addEventListener('mousedown', onDown);
    document.addEventListener('keydown', onKey, true);
    window.addEventListener('resize', onScroll);
    document.addEventListener('scroll', onScroll, true);
    return () => {
      document.removeEventListener('mousedown', onDown);
      document.removeEventListener('keydown', onKey, true);
      window.removeEventListener('resize', onScroll);
      document.removeEventListener('scroll', onScroll, true);
    };
  }, [pos]);

  const item = 'flex w-full items-center gap-2.5 rounded-lg px-2.5 py-2 text-left text-sm text-[#2A2D45] hover:bg-[#F1F0FE] focus:bg-[#F1F0FE] focus:outline-none disabled:opacity-100';

  return (
    <>
      <button
        ref={btn}
        type="button"
        aria-label="Más acciones"
        aria-haspopup="menu"
        aria-expanded={!!pos}
        onClick={e => { e.stopPropagation(); pos ? close() : open(); }}
        onKeyDown={e => e.stopPropagation()}
        className={clsx('grid h-7 w-7 place-items-center rounded-md text-[#6B7189] hover:bg-[#ECEEF5] hover:text-[#14162B]', pos && 'bg-[#ECEEF5] text-[#14162B]')}
      >
        <MoreHorizontal size={16} aria-hidden />
      </button>
      {pos && (
        <div
          ref={menu}
          role="menu"
          onClick={e => e.stopPropagation()}
          onKeyDown={e => e.stopPropagation()}
          className="rt-pop fixed z-[60] w-56 rounded-xl border border-[#E4E7F0] bg-white p-1.5 shadow-[0_18px_40px_-16px_rgba(20,22,43,.45)]"
          style={pos}
        >
          <p className="px-2.5 pb-1 pt-1.5 text-xs font-semibold text-[#8A90A6]">Mover a</p>
          {STATUSES.map(s => {
            const current = s.id === task.status;
            return (
              <button key={s.id} role="menuitem" disabled={current} className={clsx(item, current && 'cursor-default font-semibold')}
                onClick={() => { onMove(s.id); close(false); }}>
                <StatusDot status={s.id} />
                <span className="flex-1">{s.label}</span>
                {current && <Check size={14} className="text-[#5B47F5]" aria-hidden />}
              </button>
            );
          })}
          <div className="my-1 h-px bg-[#EDEFF5]" />
          <button role="menuitem" className={item} onClick={() => { close(false); onOpen(); }}>
            <PanelRightOpen size={15} className="text-[#6B7189]" aria-hidden /> Abrir detalle
          </button>
          <button role="menuitem" className={clsx(item, 'text-[#B42335] hover:bg-[#FDECEE] focus:bg-[#FDECEE]')} onClick={() => { close(false); onDelete(); }}>
            <Trash2 size={15} aria-hidden /> Eliminar tarea
          </button>
        </div>
      )}
    </>
  );
}

