const field = 'w-full rounded-lg border border-[#DADDE8] bg-white px-2.5 py-1.5 text-sm font-semibold text-[#14162B] hover:border-[#C3C7D6]';

export default function TaskDetail({ task, project, people, onChange, onMove, onDelete, onClose }: Props) {
  const [shown, setShown] = useState(false);
  const [newSub, setNewSub] = useState('');
  const [confirm, setConfirm] = useState(false);
  const [title, setTitle] = useState(task.title);
  const titleRef = useRef<HTMLTextAreaElement>(null);
  useEffect(() => {
    const el = titleRef.current;
    if (el) { el.style.height = 'auto'; el.style.height = `${el.scrollHeight}px`; }
  }, [title]);

  useEffect(() => { const id = requestAnimationFrame(() => setShown(true)); return () => cancelAnimationFrame(id); }, []);
  useEffect(() => { setTitle(task.title); setConfirm(false); }, [task.id]);
  const close = () => { setShown(false); setTimeout(onClose, 180); };
  useEffect(() => {
    const k = (e: KeyboardEvent) => { if (e.key === 'Escape') close(); };
    window.addEventListener('keydown', k);
    return () => window.removeEventListener('keydown', k);
  }, []);

  const done = task.subtasks.filter(s => s.done).length;
  const members = people.filter(p => project.memberIds.includes(p.id));

  const addSub = () => {
    const t = newSub.trim();
    if (!t) return;
    onChange({ subtasks: [...task.subtasks, { id: `s${Date.now().toString(36)}`, title: t, done: false }] });
    setNewSub('');
  };
  const commitTitle = () => {
    const t = title.trim();
    if (t.length >= 3 && t !== task.title) onChange({ title: t });
    else setTitle(task.title);
  };


  return (
    <div className="fixed inset-0 z-50" role="dialog" aria-modal="true" aria-label={`Tarea ${project.key}-${task.number}`}>
      <div onClick={close} className={clsx('absolute inset-0 bg-[#14162B]/30 transition-opacity duration-200', shown ? 'opacity-100' : 'opacity-0')} />
      <aside className={clsx('absolute inset-y-0 right-0 flex w-full max-w-[520px] flex-col bg-white shadow-2xl transition-transform duration-200 ease-out', shown ? 'translate-x-0' : 'translate-x-full')}>
        <header className="flex items-center gap-2 border-b border-[#EDEFF5] px-5 py-3">
          <span className="h-2.5 w-2.5 rounded-sm" style={{ background: project.color }} />
          <span className="truncate text-sm text-[#5A6078]">{project.name}</span>
          <span className="rt-mono rounded bg-[#F1F2F7] px-1.5 py-0.5 text-[#5A6078]">{project.key}-{task.number}</span>
          <button type="button" onClick={close} aria-label="Cerrar detalle" className="ml-auto grid h-8 w-8 place-items-center rounded-lg text-[#5A6078] hover:bg-[#F1F2F7]">
            <X size={18} aria-hidden />
          </button>
        </header>

        <div className="rt-scroll flex-1 overflow-y-auto px-5 pb-8 pt-4">
          <label htmlFor="rt-title" className="sr-only">Título</label>
          <textarea id="rt-title" ref={titleRef} rows={1} value={title} onChange={e => setTitle(e.target.value)} onBlur={commitTitle}
            onKeyDown={e => { if (e.key === 'Enter') { e.preventDefault(); (e.target as HTMLTextAreaElement).blur(); } }}
            className="rt-display w-full resize-none rounded-lg border border-transparent px-1 py-0.5 text-2xl font-semibold leading-tight text-[#14162B] hover:border-[#E4E7F0] focus:border-[#B9B0FB]" />

          <div className="mt-3 border-y border-[#EDEFF5] py-2">
            <Row icon={CircleDashed} label="Estado">
              <div className="flex items-center gap-2">
                <StatusDot status={task.status} />
                <select aria-label="Estado" value={task.status} onChange={e => onMove(e.target.value as Status)} className={field}>
                  {STATUSES.map(s => <option key={s.id} value={s.id}>{s.label}</option>)}
                </select>
              </div>
            </Row>
            <Row icon={Flag} label="Prioridad">
              <div className="flex flex-wrap gap-1" role="radiogroup" aria-label="Prioridad">
                {PRIORITIES.map(p => (
                  <button key={p.id} type="button" role="radio" aria-checked={task.priority === p.id}
                    onClick={() => onChange({ priority: p.id as Priority })}
                    className={clsx('flex items-center gap-1.5 rounded-lg border px-2 py-1 text-xs font-semibold',
                      task.priority === p.id ? 'border-[#5B47F5] bg-[#F1F0FE] text-[#14162B]' : 'border-[#E4E7F0] text-[#5A6078] hover:border-[#C3C7D6]')}>
                    <PriorityIcon p={p.id} size={12} />{p.label}
                  </button>
                ))}
              </div>
            </Row>
            <Row icon={UserRound} label="Responsable">
              <div className="flex items-center gap-2">
                <Avatar person={people.find(p => p.id === task.assigneeId)} size={26} />
                <select aria-label="Responsable" value={task.assigneeId ?? ''} onChange={e => onChange({ assigneeId: e.target.value || null })} className={field}>
                  <option value="">Sin asignar</option>
                  {members.map(p => <option key={p.id} value={p.id}>{p.name}</option>)}
                </select>
              </div>
            </Row>
            <Row icon={CalendarDays} label="Fecha límite">
              <div className="flex items-center gap-2">
                <input type="date" aria-label="Fecha límite" value={task.due ?? ''} onChange={e => onChange({ due: e.target.value || null })} className={clsx(field, 'max-w-[170px]')} />
                {task.due && <span className={clsx('text-xs font-bold', isOverdue(task) ? 'text-[#B42335]' : 'text-[#5A6078]')}>{isOverdue(task) ? 'Atrasada · ' : ''}{dueLabel(task.due)}</span>}
              </div>
            </Row>
            <Row icon={Tag} label="Etiquetas">
              <div className="flex flex-wrap gap-1">
                {Object.keys(TAGS).map(name => {
                  const on = task.tags.includes(name);
                  return (
                    <button key={name} type="button" aria-pressed={on}
                      onClick={() => onChange({ tags: on ? task.tags.filter(t => t !== name) : [...task.tags, name] })}
                      className={clsx('rounded-md', !on && 'border border-dashed border-[#D3D7E3] px-1.5 py-px text-[11px] font-semibold text-[#6B7189] hover:border-[#9EA3BC] hover:text-[#14162B]')}>
                      {on ? <TagChip name={name} small /> : name}
                    </button>
                  );
                })}
              </div>
            </Row>
          </div>

          <h3 className="mt-5 text-sm font-bold text-[#14162B]">Descripción</h3>
          <textarea aria-label="Descripción" value={task.description} rows={4} onChange={e => onChange({ description: e.target.value })}
            placeholder="Añade contexto, enlaces o criterios de aceptación…"
            className="mt-2 w-full resize-y rounded-xl border border-[#E4E7F0] bg-[#FAFBFD] px-3 py-2.5 text-sm leading-relaxed text-[#2A2D45] placeholder:text-[#9095AA] focus:border-[#B9B0FB] focus:bg-white" />

          <div className="mt-5 flex items-center gap-3">
            <h3 className="text-sm font-bold text-[#14162B]">Subtareas</h3>
            {task.subtasks.length > 0 && <span className="text-xs font-semibold text-[#5A6078]">{done} de {task.subtasks.length}</span>}
          </div>
          {task.subtasks.length > 0 && (
            <div className="mt-2 h-1.5 overflow-hidden rounded-full bg-[#EEF0F5]">
              <div className="rt-bar h-full rounded-full" style={{ width: `${(done / task.subtasks.length) * 100}%`, background: done === task.subtasks.length ? '#12A57A' : '#5B47F5' }} />
            </div>
          )}
          <ul className="mt-2 space-y-0.5">
            {task.subtasks.map(s => (
              <li key={s.id} className="group flex items-center gap-2.5 rounded-lg px-1.5 py-1.5 hover:bg-[#F7F8FB]">
                <input type="checkbox" checked={s.done} aria-label={s.title}
                  onChange={() => onChange({ subtasks: task.subtasks.map(x => (x.id === s.id ? { ...x, done: !x.done } : x)) })}
                  className="h-4 w-4 accent-[#5B47F5]" />
                <span className={clsx('flex-1 text-sm', s.done ? 'text-[#8A90A6] line-through' : 'text-[#2A2D45]')}>{s.title}</span>
                <button type="button" aria-label={`Quitar subtarea ${s.title}`} onClick={() => onChange({ subtasks: task.subtasks.filter(x => x.id !== s.id) })}
                  className="grid h-6 w-6 place-items-center rounded text-[#8A90A6] opacity-0 hover:text-[#B42335] focus:opacity-100 group-hover:opacity-100">
                  <X size={14} aria-hidden />
                </button>
              </li>
            ))}
          </ul>
          <form className="mt-1 flex gap-2" onSubmit={e => { e.preventDefault(); addSub(); }}>
            <input value={newSub} onChange={e => setNewSub(e.target.value)} placeholder="Nueva subtarea" aria-label="Nueva subtarea"
              className="flex-1 rounded-lg border border-[#E4E7F0] px-3 py-1.5 text-sm placeholder:text-[#9095AA] focus:border-[#B9B0FB]" />
            <button type="submit" disabled={!newSub.trim()} className="flex items-center gap-1 rounded-lg bg-[#F1F0FE] px-3 text-sm font-semibold text-[#4433C9] disabled:opacity-50">
              <Plus size={15} aria-hidden /> Añadir
            </button>
          </form>
        </div>

        <footer className="flex items-center gap-2 border-t border-[#EDEFF5] px-5 py-3">
          {confirm ? (
            <span className="flex items-center gap-2">
              <button type="button" onClick={onDelete} className="rounded-lg bg-[#DC3D4B] px-3 py-1.5 text-sm font-semibold text-white hover:bg-[#C22F3D]">Sí, eliminar</button>
              <button type="button" onClick={() => setConfirm(false)} className="rounded-lg px-3 py-1.5 text-sm font-semibold text-[#5A6078] hover:bg-[#F1F2F7]">Cancelar</button>
            </span>
          ) : (
            <button type="button" onClick={() => setConfirm(true)} className="-ml-2 flex items-center gap-1.5 rounded-lg px-2 py-1.5 text-sm font-semibold text-[#B42335] hover:bg-[#FDECEE]">
              <Trash2 size={15} aria-hidden /> Eliminar tarea
            </button>
          )}
          <span className="ml-auto hidden text-xs text-[#8A90A6] sm:inline">Los cambios se guardan solos</span>
        </footer>
      </aside>
    </div>
  );
}

import { useEffect, useRef, useState, type FormEvent } from 'react';
import { X } from 'lucide-react';
import clsx from 'clsx';
import type { Person, Priority, Project, Status, Task } from '../lib/types';
import { PRIORITIES, STATUSES, TAGS } from '../lib/types';
import { addDays, todayISO } from '../lib/dates';
import { PriorityIcon, TagChip } from './ui';

interface Props {
  project: Project;
  people: Person[];
  initialStatus: Status;
  defaultAssignee: string;
  onCreate: (data: Omit<Task, 'id' | 'number' | 'order'>) => void;
  onClose: () => void;
}

type Errors = Partial<Record<'title' | 'due', string>>;

const input = 'mt-1.5 w-full rounded-xl border bg-white px-3 py-2 text-sm text-[#14162B] placeholder:text-[#9095AA]';

export default function TaskForm({ project, people, initialStatus, defaultAssignee, onCreate, onClose }: Props) {
  const [title, setTitle] = useState('');
  const [description, setDescription] = useState('');
  const [status, setStatus] = useState<Status>(initialStatus);
  const [priority, setPriority] = useState<Priority>('media');
  const [assigneeId, setAssigneeId] = useState(project.memberIds.includes(defaultAssignee) ? defaultAssignee : '');
  const [due, setDue] = useState(addDays(7));
  const [tags, setTags] = useState<string[]>([]);
  const [errors, setErrors] = useState<Errors>({});
  const titleRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    titleRef.current?.focus();
    const k = (e: KeyboardEvent) => { if (e.key === 'Escape') onClose(); };
    window.addEventListener('keydown', k);
    return () => window.removeEventListener('keydown', k);
  }, []);

  const submit = (e: FormEvent) => {
    e.preventDefault();
    const errs: Errors = {};
    if (!title.trim()) errs.title = 'Escribe un título para la tarea.';
    else if (title.trim().length < 4) errs.title = 'El título es demasiado corto (mínimo 4 caracteres).';
    if (due && due < todayISO()) errs.due = 'La fecha límite no puede estar en el pasado.';
    setErrors(errs);
    if (Object.keys(errs).length) {
      (errs.title ? titleRef.current : document.getElementById('rt-new-due'))?.focus();
      return;
    }
    onCreate({ projectId: project.id, title: title.trim(), description: description.trim(), status, priority, assigneeId: assigneeId || null, tags, due: due || null, subtasks: [] });
  };

  const members = people.filter(p => project.memberIds.includes(p.id));
  const label = 'text-sm font-semibold text-[#2A2D45]';

  return (
    <div className="fixed inset-0 z-50 flex items-end justify-center sm:items-center sm:p-6" role="dialog" aria-modal="true" aria-labelledby="rt-new-title">
      <div className="rt-fade absolute inset-0 bg-[#14162B]/40" onClick={onClose} />
      <form onSubmit={submit} noValidate className="rt-pop relative flex max-h-[92vh] w-full max-w-[560px] flex-col rounded-t-3xl bg-white shadow-2xl sm:rounded-3xl">
        <header className="flex items-center gap-3 px-6 pb-2 pt-5">
          <div>
            <h2 id="rt-new-title" className="rt-display text-xl font-semibold text-[#14162B]">Nueva tarea</h2>
            <p className="text-sm text-[#5A6078]">En {project.name}</p>
          </div>
          <button type="button" onClick={onClose} aria-label="Cerrar formulario" className="ml-auto grid h-9 w-9 place-items-center rounded-xl text-[#5A6078] hover:bg-[#F1F2F7]">
            <X size={18} aria-hidden />
          </button>
        </header>

        <div className="rt-scroll space-y-4 overflow-y-auto px-6 py-3">
          <div>
            <label htmlFor="rt-new-name" className={label}>Título</label>
            <input id="rt-new-name" ref={titleRef} value={title} onChange={e => { setTitle(e.target.value); if (errors.title) setErrors({ ...errors, title: undefined }); }}
              placeholder="Ej.: Preparar demo para el cliente" aria-invalid={!!errors.title} aria-describedby="rt-err-title"
              className={clsx(input, errors.title ? 'border-[#DC3D4B]' : 'border-[#DADDE8]')} />
            {errors.title && <p id="rt-err-title" className="mt-1 text-xs font-semibold text-[#B42335]">{errors.title}</p>}
          </div>

          <div>
            <label htmlFor="rt-new-desc" className={label}>Descripción <span className="font-normal text-[#8A90A6]">(opcional)</span></label>
            <textarea id="rt-new-desc" rows={3} value={description} onChange={e => setDescription(e.target.value)}
              placeholder="Qué hay que hacer y cómo sabremos que está terminado" className={clsx(input, 'resize-none border-[#DADDE8]')} />
          </div>

          <div className="grid gap-4 sm:grid-cols-3">
            <div>
              <label htmlFor="rt-new-status" className={label}>Estado</label>
              <select id="rt-new-status" value={status} onChange={e => setStatus(e.target.value as Status)} className={clsx(input, 'border-[#DADDE8]')}>
                {STATUSES.map(s => <option key={s.id} value={s.id}>{s.label}</option>)}
              </select>
            </div>
            <div>
              <label htmlFor="rt-new-assignee" className={label}>Responsable</label>
              <select id="rt-new-assignee" value={assigneeId} onChange={e => setAssigneeId(e.target.value)} className={clsx(input, 'border-[#DADDE8]')}>
                <option value="">Sin asignar</option>
                {members.map(p => <option key={p.id} value={p.id}>{p.name}</option>)}
              </select>
            </div>
            <div>
              <label htmlFor="rt-new-due" className={label}>Fecha límite</label>
              <input id="rt-new-due" type="date" value={due} min={todayISO()} onChange={e => { setDue(e.target.value); setErrors({ ...errors, due: undefined }); }}
                aria-invalid={!!errors.due} className={clsx(input, errors.due ? 'border-[#DC3D4B]' : 'border-[#DADDE8]')} />
            </div>
          </div>
          {errors.due && <p className="-mt-2 text-xs font-semibold text-[#B42335]">{errors.due}</p>}

          <fieldset>
            <legend className={label}>Prioridad</legend>
            <div className="mt-1.5 grid grid-cols-2 gap-2 sm:grid-cols-4">
              {PRIORITIES.map(p => (
                <button key={p.id} type="button" aria-pressed={priority === p.id} onClick={() => setPriority(p.id)}
                  className={clsx('flex items-center justify-center gap-2 rounded-xl border px-3 py-2 text-sm font-semibold',
                    priority === p.id ? 'border-[#5B47F5] bg-[#F1F0FE] text-[#14162B]' : 'border-[#DADDE8] text-[#5A6078] hover:border-[#C3C7D6]')}>
                  <PriorityIcon p={p.id} />{p.label}
                </button>
              ))}
            </div>
          </fieldset>

          <fieldset>
            <legend className={label}>Etiquetas</legend>
            <div className="mt-1.5 flex flex-wrap gap-1.5">
              {Object.keys(TAGS).map(name => {
                const on = tags.includes(name);
                return (
                  <button key={name} type="button" aria-pressed={on} onClick={() => setTags(on ? tags.filter(t => t !== name) : [...tags, name])}
                    className={clsx('rounded-lg p-0.5 ring-2 transition', on ? 'ring-[#5B47F5]' : 'opacity-60 ring-transparent hover:opacity-100')}>
                    <TagChip name={name} />
                  </button>
                );
              })}
            </div>
          </fieldset>
        </div>

        <footer className="flex items-center justify-end gap-2 border-t border-[#EDEFF5] px-6 py-4">
          <button type="button" onClick={onClose} className="rounded-xl px-4 py-2 text-sm font-semibold text-[#5A6078] hover:bg-[#F1F2F7]">Cancelar</button>
          <button type="submit" className="rounded-xl bg-[#5B47F5] px-4 py-2 text-sm font-bold text-white shadow-[0_6px_16px_-8px_#5B47F5] hover:bg-[#4A37E0]">Crear tarea</button>
        </footer>
      </form>
    </div>
  );
}

import { CalendarDays, UserRound } from 'lucide-react';
import clsx from 'clsx';
import type { Person, Priority, Status, Task } from '../lib/types';
import { PRIORITIES, STATUSES, TAGS } from '../lib/types';
import { dueLabel, dueTone } from '../lib/dates';

export function Avatar({ person, size = 24, ring = false }: { person?: Person | null; size?: number; ring?: boolean }) {
  if (!person) {
    return (
      <span
        title="Sin asignar"
        className="inline-flex shrink-0 items-center justify-center rounded-full border border-dashed border-[#B5BACB] text-[#8A90A6]"
        style={{ width: size, height: size }}
      >
        <UserRound size={size * 0.55} aria-hidden />
      </span>
    );
  }
  return (
    <img
      src={person.photo}
      alt={person.name}
      title={person.name}
      loading="lazy"
      className={clsx('shrink-0 rounded-full bg-[#DCDDEB] object-cover', ring && 'ring-2 ring-white')}
      style={{ width: size, height: size }}
    />
  );
}

/** Icono de prioridad: barras crecientes; urgente es un cuadro con exclamación. */
export function PriorityIcon({ p, size = 14 }: { p: Priority; size?: number }) {
  const meta = PRIORITIES.find(x => x.id === p)!;
  if (p === 'urgente') {
    return (
      <svg width={size} height={size} viewBox="0 0 14 14" aria-label="Prioridad urgente" role="img">
        <rect x="0.5" y="0.5" width="13" height="13" rx="3.5" fill={meta.color} />
        <rect x="6.1" y="3" width="1.8" height="5" rx=".9" fill="#fff" />
        <circle cx="7" cy="10.3" r="1" fill="#fff" />
      </svg>
    );
  }
  const level = p === 'alta' ? 3 : p === 'media' ? 2 : 1;
  return (
    <svg width={size} height={size} viewBox="0 0 14 14" aria-label={`Prioridad ${meta.label.toLowerCase()}`} role="img">
      {[0, 1, 2].map(i => (
        <rect key={i} x={1 + i * 4.5} y={9 - i * 3.5} width="3" height={4 + i * 3.5} rx="1"
          fill={i < level ? meta.color : '#D5D8E3'} />
      ))}
    </svg>
  );
}

export function TagChip({ name, small }: { name: string; small?: boolean }) {
  const c = TAGS[name] ?? { fg: '#3F4A5E', bg: '#E9ECF2' };
  return (
    <span
      className={clsx('inline-flex items-center rounded-md font-semibold', small ? 'px-1.5 py-[1px] text-[11px]' : 'px-2 py-0.5 text-xs')}
      style={{ color: c.fg, background: c.bg }}
    >
      {name}
    </span>
  );
}

export function StatusDot({ status, size = 10 }: { status: Status; size?: number }) {
  const s = STATUSES.find(x => x.id === status)!;
  if (status === 'done') {
    return (
      <svg width={size + 2} height={size + 2} viewBox="0 0 12 12" aria-hidden>
        <circle cx="6" cy="6" r="6" fill={s.color} />
        <path d="M3.4 6.2l1.7 1.7 3.4-3.6" stroke="#fff" strokeWidth="1.5" fill="none" strokeLinecap="round" strokeLinejoin="round" />
      </svg>
    );
  }
  const frac = status === 'todo' ? 0 : status === 'doing' ? 0.5 : 0.75;
  const r = 3;
  const c = 2 * Math.PI * r;
  return (
    <svg width={size + 2} height={size + 2} viewBox="0 0 12 12" aria-hidden>
      <circle cx="6" cy="6" r="5" fill="none" stroke={s.color} strokeWidth="1.5" />
      {frac > 0 && (
        <circle cx="6" cy="6" r={r} fill="none" stroke={s.color} strokeWidth={r * 2}
          strokeDasharray={`${c * frac} ${c}`} transform="rotate(-90 6 6)" />
      )}
    </svg>
  );
}

export function SubtaskMeter({ task }: { task: Task }) {
  const total = task.subtasks.length;
  if (!total) return null;
  const done = task.subtasks.filter(s => s.done).length;
  const r = 6;
  const c = 2 * Math.PI * r;
  const complete = done === total;
  return (
    <span className="inline-flex items-center gap-1 text-xs font-semibold text-[#5A6078]" title={`${done} de ${total} subtareas`}>
      <svg width="16" height="16" viewBox="0 0 16 16" aria-hidden>
        <circle cx="8" cy="8" r={r} fill="none" stroke="#E1E4EE" strokeWidth="2.4" />
        <circle cx="8" cy="8" r={r} fill="none" stroke={complete ? '#12A57A' : '#5B47F5'} strokeWidth="2.4"
          strokeDasharray={`${(c * done) / total} ${c}`} strokeLinecap="round" transform="rotate(-90 8 8)" />
      </svg>
      {done}/{total}
    </span>
  );
}

export function DueChip({ task, compact }: { task: Task; compact?: boolean }) {
  if (!task.due) return compact ? null : <span className="text-xs text-[#8A90A6]">Sin fecha</span>;
  const tone = dueTone(task);
  return (
    <span
      className={clsx(
        'inline-flex items-center gap-1 whitespace-nowrap rounded-md px-1.5 py-0.5 text-xs font-semibold',
        tone === 'overdue' && 'bg-[#FDE8EA] text-[#B42335]',
        tone === 'soon' && 'bg-[#FCF1DC] text-[#8A5300]',
        tone === 'normal' && 'text-[#5A6078]',
        tone === 'done' && 'text-[#8A90A6] line-through',
      )}
    >
      <CalendarDays size={12} aria-hidden />
      {dueLabel(task.due)}
    </span>
  );
}

export function Toast({ message, actionLabel, onAction }: { message: string; actionLabel?: string; onAction?: () => void }) {
  return (
    <div role="status" className="rt-toast fixed bottom-6 left-1/2 z-[70] flex items-center gap-4 rounded-xl bg-[#14162B] py-2.5 pl-4 pr-2.5 text-sm text-white shadow-2xl">
      <span>{message}</span>
      {actionLabel && onAction && (
        <button onClick={onAction} className="rounded-lg bg-white/10 px-3 py-1 font-semibold text-[#C9C2FF] hover:bg-white/20">
          {actionLabel}
        </button>
      )}
    </div>
  );
}

import type { Person, Priority, Project, Status, Task } from '../lib/types';
