export function buildSeed(): Task[] {
  const tasks: Task[] = [];
  for (const [projectId, rows] of Object.entries(ROWS)) {
    const order: Record<string, number> = {};
    rows.forEach(([title, status, priority, assigneeId, tags, due, description, subs = []], i) => {
      order[status] = (order[status] ?? -1) + 1;
      tasks.push({
        id: `${projectId}-${i + 1}`,
        projectId,
        number: i + 1,
        title,
        description,
        status,
        priority,
        assigneeId,
        tags,
        due: due === null ? null : addDays(due),
        subtasks: subs.map(([t, done], j) => ({ id: `${projectId}-${i + 1}-s${j}`, title: t, done })),
        order: order[status],
      });
    });
  }
  return tasks;
}

