import type { Task } from './types';

const MONTHS = ['ene', 'feb', 'mar', 'abr', 'may', 'jun', 'jul', 'ago', 'sept', 'oct', 'nov', 'dic'];

export function toISO(d: Date): string {
  const m = String(d.getMonth() + 1).padStart(2, '0');
  const day = String(d.getDate()).padStart(2, '0');
  return `${d.getFullYear()}-${m}-${day}`;
}

export function parseISO(s: string): Date {
  const [y, m, d] = s.split('-').map(Number);
  return new Date(y, m - 1, d);
}

export const todayISO = () => toISO(new Date());

export function addDays(n: number): string {
  const d = new Date();
  d.setDate(d.getDate() + n);
  return toISO(d);
}

/** Días desde hoy hasta la fecha (negativo si ya pasó). */
export function daysUntil(s: string): number {
  const today = parseISO(todayISO()).getTime();
  return Math.round((parseISO(s).getTime() - today) / 86400000);
}

export function formatDate(s: string): string {
  const d = parseISO(s);
  return `${d.getDate()} ${MONTHS[d.getMonth()]}`;
}

export function dueLabel(s: string): string {
  const n = daysUntil(s);
  if (n === 0) return 'Hoy';
  if (n === 1) return 'Mañana';
  if (n === -1) return 'Ayer';
  if (n < 0 && n > -7) return `Hace ${-n} días`;
  if (n > 1 && n < 7) return `En ${n} días`;
  return formatDate(s);
}

export const isOverdue = (t: Task) => !!t.due && t.status !== 'done' && daysUntil(t.due) < 0;
export const isThisWeek = (t: Task) => !!t.due && t.status !== 'done' && daysUntil(t.due) >= 0 && daysUntil(t.due) <= 6;

export type DueTone = 'overdue' | 'soon' | 'normal' | 'done';
export function dueTone(t: Task): DueTone {
  if (!t.due) return 'normal';
  if (t.status === 'done') return 'done';
  const n = daysUntil(t.due);
  if (n < 0) return 'overdue';
  if (n <= 2) return 'soon';
  return 'normal';
}

import { useCallback, useEffect, useState } from 'react';
import type { Status, Task } from './types';
import { buildSeed } from '../data/seed';

const KEY = 'ritmo:tareas:v1';

function load(): Task[] {
  try {
    const raw = localStorage.getItem(KEY);
    if (raw) {
      const parsed = JSON.parse(raw);
      if (Array.isArray(parsed)) return parsed as Task[];
    }
  } catch {
    /* almacenamiento no disponible */
  }
  return buildSeed();
}

export function usePersisted<T>(key: string, initial: T) {
  const [value, setValue] = useState<T>(() => {
    try {
      const raw = localStorage.getItem(key);
      return raw ? (JSON.parse(raw) as T) : initial;
    } catch {
      return initial;
    }
  });
  useEffect(() => {
    try { localStorage.setItem(key, JSON.stringify(value)); } catch { /* sin almacenamiento */ }
  }, [key, value]);
  return [value, setValue] as const;
}

export function useTasks() {
  const [tasks, setTasks] = useState<Task[]>(load);

  useEffect(() => {
    try { localStorage.setItem(KEY, JSON.stringify(tasks)); } catch { /* sin almacenamiento */ }
  }, [tasks]);

  const update = useCallback((id: string, patch: Partial<Task>) => {
    setTasks(prev => prev.map(t => (t.id === id ? { ...t, ...patch } : t)));
  }, []);

  /** Mueve una tarea a una columna; si se indica beforeId, la coloca justo antes de esa tarea. */
  const move = useCallback((id: string, status: Status, beforeId: string | null = null) => {
    setTasks(prev => {
      const task = prev.find(t => t.id === id);
      if (!task) return prev;
      const col = prev
        .filter(t => t.projectId === task.projectId && t.status === status && t.id !== id)
        .sort((a, b) => a.order - b.order);
      const at = beforeId ? col.findIndex(t => t.id === beforeId) : -1;
      col.splice(at < 0 ? col.length : at, 0, { ...task, status });
      const orders = new Map(col.map((t, i) => [t.id, i]));
      return prev.map(t => {
        const o = orders.get(t.id);
        if (o === undefined) return t;
        return t.id === id ? { ...t, status, order: o } : { ...t, order: o };
      });
    });
  }, []);

  const create = useCallback((data: Omit<Task, 'id' | 'number' | 'order'>) => {
    const inProject = tasks.filter(t => t.projectId === data.projectId);
    const number = inProject.reduce((m, t) => Math.max(m, t.number), 0) + 1;
    const order = inProject.filter(t => t.status === data.status).reduce((m, t) => Math.max(m, t.order), -1) + 1;
    const created: Task = { ...data, id: `${data.projectId}-${number}-${Date.now().toString(36)}`, number, order };
    setTasks(prev => [...prev, created]);
    return created;
  }, [tasks]);

  const remove = useCallback((id: string) => setTasks(prev => prev.filter(t => t.id !== id)), []);
  const restore = useCallback((task: Task) => setTasks(prev => [...prev, task]), []);
  const reset = useCallback(() => setTasks(buildSeed()), []);

  return { tasks, update, move, create, remove, restore, reset };
}

